import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const root = new THREE.Group();
  root.userData.handlers = {};

  // Plane base: 7.0w × 0.35h, centered at origin
  const planeGeo = new THREE.PlaneGeometry(7.0, 0.35);
  const planeMat = new THREE.MeshStandardMaterial({
    color: 0x111117,
    metalness: 0.2,
    roughness: 0.6
  });
  const plane = new THREE.Mesh(planeGeo, planeMat);
  root.add(plane);

  // Top edge hairline
  const hairGeo = new THREE.PlaneGeometry(7.0, 0.006);
  const hairMat = new THREE.MeshBasicMaterial({ color: 0x23232b });

  const topHair = new THREE.Mesh(hairGeo, hairMat);
  topHair.position.set(0, 0.1785, 0.001);
  root.add(topHair);

  // Bottom edge hairline
  const botHair = new THREE.Mesh(hairGeo, hairMat.clone());
  botHair.position.set(0, -0.1785, 0.001);
  root.add(botHair);

  // Ticker content group
  const tickerGroup = new THREE.Group();
  root.add(tickerGroup);

  // Build content strip
  const entries = [
    'CAL NA-01 BEAT 28800 VPH',
    'POWER RESERVE 72H',
    'CASE 40.5 MM 904L',
    'REF 5811 IN STOCK',
    'WAITLIST 1204',
    'NEXT FITTING JUL 18'
  ];

  const { strip, length: stripLength } = buildContentStrip(entries, ctx);
  tickerGroup.add(strip);

  // Duplicate strip for seamless loop
  const stripDupe = strip.clone();
  stripDupe.position.x = stripLength;
  tickerGroup.add(stripDupe);

  // Apply fly-through primitive for leftward scrolling (0.4 units/sec)
  if (ctx.primitives && ctx.primitives['fly-through']) {
    ctx.primitives['fly-through'](tickerGroup, {
      speed: 0.4,
      depthUnits: 0
    });
  }

  // Add edge fade masks
  addEdgeFades(root);

  // Cleanup
  root.userData.cleanup = () => {
    planeMat.dispose();
    hairMat.dispose();
    planeGeo.dispose();
    hairGeo.dispose();

    root.traverse(child => {
      if (child.geometry && ![planeGeo, hairGeo].includes(child.geometry)) {
        child.geometry.dispose();
      }
      if (child.material && ![planeMat, hairMat].includes(child.material)) {
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return root;
}

function buildContentStrip(entries, ctx) {
  const strip = new THREE.Group();
  let xPos = -3.5;

  entries.forEach((text, idx) => {
    // Create MSDF text mesh
    const textMesh = ctx.fontAtlas.createTextMesh(text, {
      fontSize: 0.13,
      fontWeight: 700,
      color: 0xe8ecf2,
      align: 'left',
      anchorX: 'left',
      anchorY: 'middle',
      letterSpacing: 0.06
    });
    textMesh.position.set(xPos, 0, 0.02);
    strip.add(textMesh);

    // Advance past text (estimate ~0.065 units per mono character)
    const textWidth = text.length * 0.065;
    xPos += textWidth + 0.5;

    // Add vertical accent separator tick (except after last entry)
    if (idx < entries.length - 1) {
      const tickGeo = new THREE.PlaneGeometry(0.02, 0.14);
      const tickMat = new THREE.MeshBasicMaterial({
        color: 0xff2a38,
        emissive: 0xff2a38,
        emissiveIntensity: 1.5
      });
      const tick = new THREE.Mesh(tickGeo, tickMat);
      tick.position.set(xPos, 0, 0.02);
      strip.add(tick);

      // Advance past tick with gaps (0.5 + 0.02 tick + 0.5)
      xPos += 1.02;
    }
  });

  return {
    strip,
    length: xPos + 3.5
  };
}

function addEdgeFades(parent) {
  const fadeGeo = new THREE.PlaneGeometry(0.6, 0.35);

  const fadeMat = new THREE.MeshBasicMaterial({
    color: 0x0b0b10,
    transparent: true,
    blending: THREE.MultiplyBlending,
    opacity: 0.75
  });

  // Left fade (0.6 units wide at left edge)
  const leftFade = new THREE.Mesh(fadeGeo, fadeMat);
  leftFade.position.set(-3.2, 0, 0.05);
  parent.add(leftFade);

  // Right fade (mirrored)
  const rightFadeMat = fadeMat.clone();
  const rightFade = new THREE.Mesh(fadeGeo, rightFadeMat);
  rightFade.position.set(3.2, 0, 0.05);
  rightFade.scale.x = -1;
  parent.add(rightFade);
}
